package app

import (
	"bytes"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/colorprofile"
)

// Spike DEVDESK-198 criterion 4: the profile is applied at the output, by the
// program, not by Render().
func TestSpikeProfileAppliedByProgram(t *testing.T) {
	for _, tc := range []struct {
		name    string
		profile colorprofile.Profile
		want    string
		notWant string
	}{
		{"truecolor", colorprofile.TrueColor, "38;2;", ""},
		{"ansi256", colorprofile.ANSI256, "38;5;", "38;2;"},
		{"ascii", colorprofile.Ascii, "", "38;"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			a := router(t, &fakeView{title: "view", body: "hello"})
			var out bytes.Buffer
			p := tea.NewProgram(a, tea.WithInput(nil), tea.WithOutput(&out),
				tea.WithWindowSize(100, 30), tea.WithoutSignalHandler(), tea.WithColorProfile(tc.profile))
			go func() { time.Sleep(400 * time.Millisecond); p.Quit() }()
			if _, err := p.Run(); err != nil {
				t.Fatal(err)
			}
			got := out.String()
			if !strings.Contains(got, "hello") {
				t.Fatalf("no content rendered: %q", got[:min(len(got), 200)])
			}
			if tc.want != "" && !strings.Contains(got, tc.want) {
				t.Errorf("want %q in output", tc.want)
			}
			if tc.notWant != "" && strings.Contains(got, tc.notWant) {
				t.Errorf("did not want %q in output", tc.notWant)
			}
			t.Logf("alt screen enter (1049h): %v, bytes: %d", strings.Contains(got, "\x1b[?1049h"), len(got))
		})
	}
}
// The assertion is on the rendered View rather than on lines()[0], because what
// the rule is about is the first row on screen: a padding that lines() carried
// and View dropped would pass a test written the other way. Nothing strips
// escape sequences here — under `go test` lipgloss finds no TTY and emits none.
func TestTheBodyOpensOnABlankLine(t *testing.T) {
	rows := strings.Split(sized(t, 40).Render(), "\n")

	if strings.TrimSpace(rows[0]) != "" {
		t.Errorf("the first rendered row is %q, want a blank line between the border and the content", rows[0])
	}
	if !strings.Contains(rows[1], "Build") {
		t.Errorf("the second row is %q, want the first section title", rows[1])
	}
}

// The padding scrolls away rather than being repainted at every offset: it
// belongs to the body, not to the window onto it.
func TestTheTopPaddingScrollsAway(t *testing.T) {
	rows := strings.Split(press(t, sized(t, 5), "down").Render(), "\n")

	if strings.TrimSpace(rows[0]) == "" {
		t.Error("the first row is still blank one line down, so the padding is pinned to the window rather than to the body")
	}
}

func TestTheBodyNamesTheBuild(t *testing.T) {
	}
}

// Rule 131: exactly one blank line above the form.
func TestTheFormOpensWithOneBlankLine(t *testing.T) {
	lines := strings.Split(newModel(t).Render(), "\n")
	if len(lines) < 3 {
		t.Fatalf("the view rendered %d lines", len(lines))
	}
	if strings.TrimSpace(lines[0]) != "" {
		t.Errorf("line 1 = %q, want a blank padding line", lines[0])
	}
	if strings.TrimSpace(lines[1]) == "" {
		t.Error("line 2 is blank too; Rule 131 allows exactly one")
	}
}

// The header names the context, as every other view's does. Editing
// workspaces_dir in the wrong context is otherwise a silent mistake — the
// fields look identical in all of them.
func TestTheHeaderNamesTheContextItEdits(t *testing.T) {
	m := newModel(t)

	var got string
	for _, info := range m.GetHeaderInfo("dev") {
		if info.Key == "Context" {
			got = info.Value
		}
	}
	if got != "dev" {
		t.Errorf("the header's Context reads %q, want the context the router passed", got)
		t.Errorf("the repositories node reads %q, want the two repositories", got)
	}
}

// The case the boolean couldn't say. `scan.enable_secret` turned off, a
// missing tool, or entries written before the image scan had a secrets
// step: in all three cases the cache carries no verdict, and `0` would read
// "no target carries any" for targets nobody has looked at.
func TestAnInventoryWithNoVerdictAtAllPrintsNoCount(t *testing.T) {
	m, _ := loadedModel(t)
	m = feed(t, m, PostureMsg{Posture: postureWith(
		[]*bool{nil, nil},
		[]*bool{nil},
	)})

	repos, images := healthColumns(m)

	for _, tt := range []struct {
		side  []string
		head  string
		label string
	}{
		{images, "Images", "images"},
		{repos, "Repositories", "repositories"},
	} {
		got := nodeUnder(tt.side, tt.head, "secrets")
		if !strings.Contains(got, unknownValue()) {
			t.Errorf("the %s node reads %q with no verdict known, want %q", tt.label, got, unknownValue())
		}
		if strings.Contains(got, "0") {
			t.Errorf("the %s node reads %q — a zero says nobody carries a secret, of targets nobody looked at",
				tt.label, got)
		}
	}
}

// A verdict known on only part of the set is enough to display the count:
// it's then a floor, and a nonzero floor is actionable. That's what tells
// apart "we know nothing" from "we already know there is at least one".
func TestAPartiallyKnownInventoryStillReportsWhatItKnows(t *testing.T) {
	m, _ := loadedModel(t)
}

// A textinput with Width 0 shows one rune of its placeholder, so an unsized
// form read "8" and "h". The width has to be set, and it has to reach the
// inputs whichever way the form was built or resized.
func TestTheFormShowsWholePlaceholders(t *testing.T) {
	f := NewForwardForm(100)
	view := f.View()
	for _, want := range []string{"8080", "host:port"} {
		if !strings.Contains(view, want) {
			t.Errorf("the form renders %q, want the whole placeholder %q", view, want)
		}
	}

